        if (genesisPool == address(0) || block.timestamp >= genesisMaturityTime) {
            return 0;
        }

        return IGenesisPool(genesisPool).balanceOf(account);
    }

    function _withdrawableBalance(address account) internal view returns (uint256) {
        return _balanceOf(account) - _lockedGenesisBalance(account);
    }

