function setGenesisPoolInfo(GenesisInfo calldata _genesisInfo, TokenAllocation calldata _allocationInfo, address _auction) external onlyManager(){
    require(poolStatus == PoolStatus.DEFAULT, "INITIALIZED");
    require(_auction != address(0), "ZA");
    genesisInfo = _genesisInfo;

    genesisInfo.duration = BlackTimeLibrary.epochMultiples(genesisInfo.duration);
    genesisInfo.startTime = BlackTimeLibrary.epochStart(genesisInfo.startTime);

    allocationInfo.proposedNativeAmount = _allocationInfo.proposedNativeAmount;

function setAuction(address _auction) external onlyManager {
    require(_auction != address(0), "ZA");
    require(poolStatus == PoolStatus.NATIVE_TOKEN_DEPOSITED, "INS");
    auction = IAuction(_auction);
}

function setMaturityTime(uint256 _maturityTime) external onlyManager{
    genesisInfo.maturityTime = _maturityTime;
}

function setStartTime(uint256 _startTime) external onlyManager{

require(genesisPoolInfo.nativeToken == nativeToken, "MISMATCH");

require(genesisFactory.getGenesisPool(nativeToken) == address(0), "ACTIVE_GENESIS");
genesisPool = genesisFactory.createGenesisPool(_sender, nativeToken, _fundingToken);

require(genesisPool != address(0), "ZA");

address auction = auctionFactory.auctions(auctionIndex);
auction = auction == address(0) ? auctionFactory.auctions(0) : auction;
require(auction != address(0) && auctionFactory.isAuction(auction), "!AUCTION");

IERC20(nativeToken).safeTransferFrom(_sender, genesisPool, allocationInfo.proposedNativeAmount);
if(!isNativeToken[nativeToken]){
    nativeTokens.push(nativeToken); 
    isNativeToken[nativeToken] = true;
}

    TOKEN.safeTransfer(msg.sender, _amount);
    emit Withdraw(msg.sender, _amount);
}

function _deductBalance(uint256 _amount) internal {
    uint256 gaugeDeduction = _balances[msg.sender] <= _amount ? _balances[msg.sender] : _amount;
    uint256 genesisDeduction = _amount - gaugeDeduction;

    _balances[msg.sender] = _balances[msg.sender] - gaugeDeduction;
    if(genesisPool != address(0) && genesisDeduction > 0){
        IGenesisPool(genesisPool).deductAmount(msg.sender, genesisDeduction);
    }
}

///@notice withdraw all TOKEN and harvest rewardToken
function withdrawAllAndHarvest() external {

function _depositsForGenesis(address _tokenOwner, uint256 _timestamp, uint256 _totalAmount) internal updateReward(address(0)) {       
    TOKEN.safeTransferFrom(msg.sender, address(this), _totalAmount);
    _totalSupply = _totalSupply + _totalAmount;
    if (_timestamp > maturityTime[_tokenOwner]) {
        maturityTime[_tokenOwner] = _timestamp;
    }
    if (_timestamp > genesisMaturityTime) {
        genesisMaturityTime = _timestamp;
    }

    emit DepositsForGenesis(_tokenOwner, _totalAmount);
}

///@notice deposit all TOKEN of msg.sender
function depositAll() external {
    _deposit(TOKEN.balanceOf(msg.sender), msg.sender);
}

///@notice deposit amount TOKEN
function deposit(uint256 amount) external {

function _balanceOf(address account) internal view returns (uint256) {
    uint256 balance = _balances[account];
    if(genesisPool != address(0)) balance += IGenesisPool(genesisPool).balanceOf(account);
    return balance;
}

function _lockedGenesisBalance(address account) internal view returns (uint256) {
    if (genesisPool == address(0) || block.timestamp >= genesisMaturityTime) {
        return 0;
    }

    return IGenesisPool(genesisPool).balanceOf(account);
}

function _withdrawableBalance(address account) internal view returns (uint256) {
    return _balanceOf(account) - _lockedGenesisBalance(account);
}

